namespace Schoolbox\LearningAnalytics\Results;

use Schoolbox\LearningAnalytics\Sorter;

class Averages {

    /**
     * An array of unitId-(user, taskValue)
     * Generated by boxplot section
     *
     * Sequential dependency, to save some processing
     *
     * @var array
     */
    private $allResults = array();

    /**
     * An associative array of userId/average values
     *
     * @var array
     */
    private $allAverages = array();

    /**
     * Constructor
     *
     * @param array $allResults
     */
    public function __construct($allResults) {
        $this->setAllResults($allResults);
        
        $this->process();
    }

    /**
     * Process
     */
    private function process() {
        $allAverages = array();

        foreach ($this->getAllResults() as $taskId => $currentTaskResult) {
            foreach ($currentTaskResult as $userResult) {
                $key = $userResult['user']->getId();

                /* Store the user object
                 */
                $allAverages[$key]['user'] = $userResult['user'];

                /* Initialise mark stack
                 * Initialise average
                 */
                if (!is_array($allAverages[$key]['marks'])) {
                    $allAverages[$key]['marks'] = [];
                    $allAverages[$key]['average'] = 0;
                }

                /* Store a set of marks for calculating averages later
                 */
                if (is_numeric($userResult['value'])) {
                    $allAverages[$key]['marks'][] = $userResult['value'];
                }
            }
        }

        /* Calculate averages for each user
         */
        foreach ($allAverages as $key => $pieces) {
            if (count($pieces['marks'])) {
                $allAverages[$key]['average'] = array_sum($pieces['marks']) / count($pieces['marks']);
            }
        }

        $this->setAllAverages($allAverages);
    }

    /**
     * Sort in ascending order
     *
     * @return array
     */
    public function findAscending() {
        $sorter = new Sorter($this->getAllAverages());

        return $sorter->findAscending('average');
    }

    /**
     * Sort in descending order
     *
     * @return array
     */
    public function findDescending() {
        $sorter = new Sorter($this->getAllAverages());

        return $sorter->findDescending('average');
    }

    /* Getters/Setters
     */

    /**
     * Set all averages
     *
     * @param array $allAverages
     */
    private function setAllAverages($allAverages)
    {
        $this->allAverages = $allAverages;
    }

    /**
     * Get all averages
     *
     * @return array
     */
    private function getAllAverages()
    {
        return $this->allAverages;
    }

    /**
     * Set all results
     *
     * @param array $allResults
     */
    private function setAllResults($allResults)
    {
        $this->allResults = $allResults;
    }

    /**
     * Get all results
     *
     * @return array
     */
    private function getAllResults()
    {
        return $this->allResults;
    }
}